import{_ as o,C as n,o as t,c as r,a2 as a,b as d,w as s,a as l,E as c,a3 as h}from"./chunks/framework.CZqXuAiL.js";const v=JSON.parse(`{"title":"Attack Mode","description":"NitroCord's attack-mode state machine — engage and disengage thresholds, what escalates during an attack, kick suppression, the NitroAttackModeEvent, tuning guidance, and how verified players sail through floods.","frontmatter":{"title":"Attack Mode","description":"NitroCord's attack-mode state machine — engage and disengage thresholds, what escalates during an attack, kick suppression, the NitroAttackModeEvent, tuning guidance, and how verified players sail through floods."},"headers":[],"relativePath":"nitrocord/architecture/attack-mode.md","filePath":"nitrocord/architecture/attack-mode.md","lastUpdated":1785341162000}`),p={name:"nitrocord/architecture/attack-mode.md"};function g(k,e,u,m,y,f){const i=n("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="attack-mode" tabindex="-1">Attack Mode <a class="header-anchor" href="#attack-mode" aria-label="Permalink to &quot;Attack Mode&quot;">​</a></h1><blockquote><p><strong>Normal checks for normal days. Escalation for the bad minutes.</strong> Attack mode is NitroCord&#39;s global state machine: when the proxy-wide connection rate crosses a threshold, a whole tier of dormant defenses wakes up — and stands down again on its own once the flood is over.</p></blockquote><nav class="table-of-contents"><ul><li><a href="#what-attack-mode-is">What attack mode is</a></li><li><a href="#the-state-machine">The state machine</a><ul><li><a href="#thresholds">Thresholds</a></li></ul></li><li><a href="#what-changes-during-attack-mode">What changes during attack mode</a><ul><li><a href="#server-list-pings-during-attacks">Server list pings during attacks</a></li><li><a href="#silent-closes-instead-of-kicks">Silent closes instead of kicks</a></li><li><a href="#tcp-fingerprinting">TCP fingerprinting</a></li><li><a href="#name-heuristics">Name heuristics</a></li><li><a href="#anti-hang-read-timeouts">Anti-hang read timeouts</a></li></ul></li><li><a href="#observing-transitions-nitroattackmodeevent">Observing transitions: NitroAttackModeEvent</a></li><li><a href="#tuning-guidance">Tuning guidance</a><ul><li><a href="#small-network-one-proxy-up-to-a-few-hundred-players">Small network (one proxy, up to a few hundred players)</a></li><li><a href="#large-network-several-proxies-thousands-of-players">Large network (several proxies, thousands of players)</a></li></ul></li><li><a href="#the-verified-whitelist-during-attacks">The verified whitelist during attacks</a></li><li><a href="#early-stop-when-the-flood-collapses">Early stop: when the flood collapses</a></li><li><a href="#likeliness-scoring">Likeliness scoring</a></li><li><a href="#the-attack-log">The attack log</a></li><li><a href="#related-pages">Related pages</a></li></ul></nav><hr><h2 id="what-attack-mode-is" tabindex="-1">What attack mode is <a class="header-anchor" href="#what-attack-mode-is" aria-label="Permalink to &quot;What attack mode is&quot;">​</a></h2><p>Most NitroCord checks run around the clock: the firewall gate, rate limiting, reconnect verification, anti-VPN, country blocking and packet flood scoring never sleep. A second tier of checks is different — they are powerful but too aggressive (or too easy to abuse for false positives) to run against everyday traffic, so they stay dormant until the proxy is measurably under attack.</p><p>Attack mode is the switch. While it is engaged:</p><ul><li>the dormant checks arm (TCP fingerprinting, name heuristics, DNS check, tab-complete filter),</li><li>expensive work is bypassed (pings served from cache, no event dispatch, no backend contact),</li><li>and under extreme rates, kicks stop being written at all.</li></ul><p>It engages and disengages <strong>automatically</strong> — there is no command to toggle it and no admin action required. Verified players are unaffected; see <a href="#the-verified-whitelist-during-attacks">the whitelist interaction</a>.</p><hr><h2 id="the-state-machine" tabindex="-1">The state machine <a class="header-anchor" href="#the-state-machine" aria-label="Permalink to &quot;The state machine&quot;">​</a></h2>',11)),(t(),d(h,null,{default:s(()=>[c(i,{id:"mermaid-45",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20Normal%0A%20%20%20%20Normal%20--%3E%20Attack%3A%20connection%20rate%20%E2%89%A5%20activate-connections-per-second%20(default%2040%2Fs)%0A%20%20%20%20Attack%20--%3E%20Attack%3A%20rate%20stays%20%E2%89%A5%20threshold%20(below-threshold%20timer%20keeps%20resetting)%0A%20%20%20%20Attack%20--%3E%20Normal%3A%20rate%20below%20threshold%20for%20deactivate-delay-seconds%20(default%2060)%20consecutive%20seconds%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>Mechanics, exactly as implemented:</p><ul><li><strong>The metric</strong> is new LOGIN-intent connections per second, counted proxy-wide in a one-second sliding window. Server list pings are tracked separately and never engage attack mode on their own.</li><li><strong>Engage</strong> the moment the measured rate reaches <code>attack.activate-connections-per-second</code>.</li><li><strong>Disengage</strong> only after the rate has stayed below the threshold for <code>attack.deactivate-delay-seconds</code> consecutive seconds — a brief dip in a long flood does not flap the state. With <code>attack.early-stop</code> enabled, a collapsed join rate disengages sooner; see <a href="#early-stop-when-the-flood-collapses">early stop</a>.</li><li><strong>Evaluated constantly.</strong> The state is re-evaluated lazily on every <code>isAttackMode()</code> query and once per second on the <code>nitrocord-attack-mode</code> daemon thread, so transitions are detected even when no new connections are arriving (which is exactly when disengagement happens).</li><li><strong>Live configuration.</strong> Thresholds are read from the current <code>protection.toml</code> snapshot on every evaluation — <code>/nitrocord reload</code> retunes the machine without a restart. Setting <code>attack.enabled = false</code> disengages attack mode immediately if it was active.</li><li><strong>Every transition is observable</strong>: logged to the console (the <code>attack-mode-on</code> / <code>attack-mode-off</code> messages from <code>nitrocord.toml</code>) and announced to plugins through <code>NitroAttackModeEvent</code>.</li></ul><h3 id="thresholds" tabindex="-1">Thresholds <a class="header-anchor" href="#thresholds" aria-label="Permalink to &quot;Thresholds&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>attack.enabled</code></td><td><code>true</code></td><td>Master switch for the state machine</td></tr><tr><td><code>attack.activate-connections-per-second</code></td><td><code>40</code></td><td>Proxy-wide new connections per second that engage attack mode</td></tr><tr><td><code>attack.deactivate-delay-seconds</code></td><td><code>60</code></td><td>Consecutive seconds below the threshold before disengaging</td></tr><tr><td><code>attack.early-stop</code></td><td><code>true</code></td><td>Allow disengaging early when the join rate collapses</td></tr><tr><td><code>attack.early-stop-joins-per-window</code></td><td><code>8</code></td><td>Joins per window below which the early stop triggers</td></tr><tr><td><code>attack.early-stop-window-seconds</code></td><td><code>5</code></td><td>Rolling window size (seconds) joins are counted in</td></tr><tr><td><code>attack.early-stop-sustain-seconds</code></td><td><code>3</code></td><td>Consecutive quiet windows required before disengaging early</td></tr><tr><td><code>antiddos.kick-suppression-connections-per-second</code></td><td><code>150</code></td><td>During attack mode, rate at which kicks turn into silent RSTs</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Ping floods don&#39;t flip the switch</p><p>A pure MOTD/ping flood does not engage attack mode — it is absorbed by the per-IP ping rate limit and the cached MOTD. Attack mode measures login attempts, the traffic class that actually costs a proxy real work.</p></div><hr><h2 id="what-changes-during-attack-mode" tabindex="-1">What changes during attack mode <a class="header-anchor" href="#what-changes-during-attack-mode" aria-label="Permalink to &quot;What changes during attack mode&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Behavior</th><th>Normal</th><th>Attack mode engaged</th></tr></thead><tbody><tr><td>Server list pings</td><td><code>ProxyPingEvent</code> fires; responses may pass through to backends; fresh responses are cached</td><td>Served directly from the synthesized cache — no event dispatch, no backend contact, null-ping proof</td></tr><tr><td>TCP fingerprinting</td><td>Dormant (<code>tcp-fingerprint.only-during-attack = true</code>)</td><td>Engages once the rate also reaches <code>tcp-fingerprint.required-connections-per-second</code> (default 100)</td></tr><tr><td>Name-pattern check</td><td>Passes silently</td><td>Compares each joining name against recent joins (Levenshtein similarity)</td></tr><tr><td>Strange-name check</td><td>Passes silently</td><td>Denies randomly generated-looking usernames</td></tr><tr><td>DNS check</td><td>Off</td><td>Joins whose handshake host is a bare IP literal earn a violation strike</td></tr><tr><td>Pre-login read timeout</td><td>Velocity default</td><td>Shrinks to <code>anti-hang.attack-timeout-ms</code> (default 2,000 ms)</td></tr><tr><td>Tab-complete filter</td><td>Off</td><td>Scores tab-complete expressions; exploit-like input earns a strike</td></tr><tr><td>Kick delivery</td><td>Configured MiniMessage kick message</td><td>Above 150 conn/s: no kick packet at all — the connection dies with a silent TCP RST</td></tr><tr><td>All always-on checks</td><td>On</td><td>On, unchanged</td></tr></tbody></table><h3 id="server-list-pings-during-attacks" tabindex="-1">Server list pings during attacks <a class="header-anchor" href="#server-list-pings-during-attacks" aria-label="Permalink to &quot;Server list pings during attacks&quot;">​</a></h3><p>This is the biggest behavioral change and the reason NitroCord survives null-ping floods. While attack mode is engaged and a fresh cached response exists (younger than <code>motd.cache-seconds</code>, default 5 s):</p><ol><li>The status request is answered directly from the snapshot. <code>ProxyPingEvent</code> is <strong>not</strong> fired — during a flood the plugin event path is itself attack surface — and no backend server is contacted.</li><li>If no fresh snapshot exists, a local ping is synthesized immediately from your configuration; backend ping-passthrough is skipped.</li><li>If even that fails, the proxy falls back to the last cached response or another synthesized ping. A NitroCord proxy always answers the server list.</li></ol><p>Your custom MOTD rotation and fake player count keep applying throughout — cached responses are passed through the same synthesizer. The one thing that does <strong>not</strong> survive is the favicon: it is by far the largest field of a ping response and bots do not render it, so every attack-mode answer is served without it, shrinking each reply to a ping flood. The favicon returns the moment attack mode disengages.</p><h3 id="silent-closes-instead-of-kicks" tabindex="-1">Silent closes instead of kicks <a class="header-anchor" href="#silent-closes-instead-of-kicks" aria-label="Permalink to &quot;Silent closes instead of kicks&quot;">​</a></h3><p>Writing a disconnect packet costs orders of magnitude more than resetting a socket. When attack mode is engaged <strong>and</strong> the connection rate reaches <code>antiddos.kick-suppression-connections-per-second</code> (default 150), denied connections stop receiving kick messages: the channel is closed with <code>SO_LINGER 0</code>, the kernel sends a TCP RST, and both sides move on. Below that rate, or outside attack mode, players always see the configured kick message.</p><h3 id="tcp-fingerprinting" tabindex="-1">TCP fingerprinting <a class="header-anchor" href="#tcp-fingerprinting" aria-label="Permalink to &quot;TCP fingerprinting&quot;">​</a></h3><p>NitroCord&#39;s signature bot filter reads the kernel&#39;s <code>tcp_info</code> for each new connection and flags stacks that don&#39;t behave like a real Minecraft client — suspicious MSS values, non-Windows option negotiation, raw-socket stacks, and MTU-mangling middleboxes. Because it judges the client&#39;s operating system, it is deliberately attack-gated by default: it only runs while attack mode is engaged <strong>and</strong> the proxy-wide rate has reached <code>tcp-fingerprint.required-connections-per-second</code> (default 100). A flagged connection earns a <code>TCP_FINGERPRINT</code> violation strike and a silent RST. Set <code>tcp-fingerprint.only-during-attack = false</code> to run it around the clock.</p><h3 id="name-heuristics" tabindex="-1">Name heuristics <a class="header-anchor" href="#name-heuristics" aria-label="Permalink to &quot;Name heuristics&quot;">​</a></h3><p>Botnets generate usernames from templates. During attack mode:</p><ul><li><strong>Name-pattern</strong> compares each joining name against the most recent joins using Levenshtein similarity — names matching a repeating template beyond <code>name-checks.pattern-min-match-percent</code> are denied. A rejoining player whose own name is still in the tiny comparison window is explicitly skipped.</li><li><strong>Strange-name</strong> flags names with improbable runs of capitals or digits.</li></ul><p>Both pass silently outside attack mode, so unusual but legitimate names never trip them on a normal day.</p><h3 id="anti-hang-read-timeouts" tabindex="-1">Anti-hang read timeouts <a class="header-anchor" href="#anti-hang-read-timeouts" aria-label="Permalink to &quot;Anti-hang read timeouts&quot;">​</a></h3><p>Pre-login connections that connect but never send anything pile up during floods. While attack mode is engaged, stalled pre-login connections are reaped after <code>anti-hang.attack-timeout-ms</code> (default 2,000 ms) instead of the normal read timeout — before they accumulate into a resource problem.</p><hr><h2 id="observing-transitions-nitroattackmodeevent" tabindex="-1">Observing transitions: NitroAttackModeEvent <a class="header-anchor" href="#observing-transitions-nitroattackmodeevent" aria-label="Permalink to &quot;Observing transitions: NitroAttackModeEvent&quot;">​</a></h2><p>Plugins are notified after every transition through <code>com.nitrocord.api.events.NitroAttackModeEvent</code>. The event is purely informational: the transition has already been applied when it fires, and listeners cannot cancel or change it.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Subscribe</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> onAttackMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(NitroAttackModeEvent event) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (event.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isAttackMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">warn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Attack mode engaged at {} conn/s&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, event.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getConnectionsPerSecond</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Attack mode disengaged (rate now {} conn/s)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        event.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getConnectionsPerSecond</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>getConnectionsPerSecond()</code> carries the proxy-wide rate measured at the exact moment of the transition. Typical uses: alerting (Discord webhooks), switching a lobby into a lightweight &quot;under attack&quot; mode, or feeding your own metrics pipeline. See <a href="/pingless-studios-docs/nitrocord/user-guide/api">Plugin API Events</a>.</p><hr><h2 id="tuning-guidance" tabindex="-1">Tuning guidance <a class="header-anchor" href="#tuning-guidance" aria-label="Permalink to &quot;Tuning guidance&quot;">​</a></h2><p>The defaults target a typical mid-size network. Adjust to your join patterns, not to superstition — the one rule is: <strong>attack mode must never engage on your busiest legitimate minute.</strong></p><h3 id="small-network-one-proxy-up-to-a-few-hundred-players" tabindex="-1">Small network (one proxy, up to a few hundred players) <a class="header-anchor" href="#small-network-one-proxy-up-to-a-few-hundred-players" aria-label="Permalink to &quot;Small network (one proxy, up to a few hundred players)&quot;">​</a></h3><p>Legitimate join bursts on a small network rarely exceed a handful per second, even after a restart.</p><table tabindex="0"><thead><tr><th>Knob</th><th>Suggested</th><th>Why</th></tr></thead><tbody><tr><td><code>attack.activate-connections-per-second</code></td><td><code>20</code>–<code>40</code></td><td>Even a modest bot join flood is far above your organic rate</td></tr><tr><td><code>attack.deactivate-delay-seconds</code></td><td><code>60</code></td><td>Default is fine; short floods shouldn&#39;t flap the state</td></tr><tr><td><code>antiddos.kick-suppression-connections-per-second</code></td><td><code>150</code></td><td>Default is fine; small floods rarely reach it</td></tr><tr><td><code>tcp-fingerprint.required-connections-per-second</code></td><td><code>60</code>–<code>100</code></td><td>Lower it if you want fingerprinting to arm earlier</td></tr></tbody></table><h3 id="large-network-several-proxies-thousands-of-players" tabindex="-1">Large network (several proxies, thousands of players) <a class="header-anchor" href="#large-network-several-proxies-thousands-of-players" aria-label="Permalink to &quot;Large network (several proxies, thousands of players)&quot;">​</a></h3><p>Hub restarts, network-wide events and matchmaking spikes can produce legitimate join bursts of 100+ per second. Measure your real peak first (<code>/nitrocord stats</code> shows the live connection rate), then set the threshold clearly above it.</p><table tabindex="0"><thead><tr><th>Knob</th><th>Suggested</th><th>Why</th></tr></thead><tbody><tr><td><code>attack.activate-connections-per-second</code></td><td><code>100</code>–<code>150</code></td><td>Above your highest observed legitimate burst</td></tr><tr><td><code>attack.deactivate-delay-seconds</code></td><td><code>60</code>–<code>120</code></td><td>Rolling restarts produce rolling dips; don&#39;t disengage mid-event</td></tr><tr><td><code>tcp-fingerprint.required-connections-per-second</code></td><td>match or exceed the engage threshold</td><td>Fingerprinting should only arm at real flood rates</td></tr><tr><td><code>antiddos.kick-suppression-connections-per-second</code></td><td>above your legitimate peak</td><td>Kicks must stay visible for real players</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Don&#39;t set the engage threshold below your organic peak</p><p>If attack mode engages on legitimate traffic, the dormant checks start judging real players: name heuristics apply to normal joins, the DNS check denies players connecting by IP, and read timeouts shrink. Pick a threshold with headroom, and let the always-on checks handle the rest.</p></div><div class="warning custom-block"><p class="custom-block-title">HAProxy / proxy-protocol setups</p><p>Behind a load balancer with <code>proxy-protocol</code> enabled, the accept-time gate sees the balancer&#39;s address, not the client&#39;s — TCP fingerprinting inspects the wrong socket. Disable <code>tcp-fingerprint</code> on such setups; everything else is unaffected.</p></div><hr><h2 id="the-verified-whitelist-during-attacks" tabindex="-1">The verified whitelist during attacks <a class="header-anchor" href="#the-verified-whitelist-during-attacks" aria-label="Permalink to &quot;The verified whitelist during attacks&quot;">​</a></h2><p>The persistent whitelist is what makes attack mode free for your regulars. When a player completes a full login, their address is marked verified and remembered for <code>whitelist.survive-days</code> (default 30 days). A verified address:</p><ul><li><strong>skips every remaining accept-time check</strong> — no cached anti-VPN verdict, no fingerprinting, straight into the pipeline;</li><li><strong>skips the entire handshake gate</strong> — no rate limit, no reconnect verification, no offline anti-VPN lookup, no country check.</li></ul><p>A completed login is the strongest legitimacy signal NitroCord has: the client already passed every gate once. So while an attack rages, your verified players rejoin exactly as fast as on a normal day, and only genuinely new addresses pay the full cost of the escalated gates. Marking an address verified also lifts any active firewall ban on it and wipes its violation history — a true fresh start.</p><p>The whitelist persists to <code>nitrocord/whitelist.txt</code>, survives proxy restarts, and purges entries not seen within the configured window. Genuine players only ever experience the strict gates once: on their very first join.</p><hr><h2 id="early-stop-when-the-flood-collapses" tabindex="-1">Early stop: when the flood collapses <a class="header-anchor" href="#early-stop-when-the-flood-collapses" aria-label="Permalink to &quot;Early stop: when the flood collapses&quot;">​</a></h2><p>The 60-second deactivation delay is deliberately conservative — it exists so a bursty attack cannot flap the mode. But many real floods end abruptly: the botnet is firewalled faster than it rotates addresses, or the attacker simply gives up. Waiting a full extra minute with every check escalated punishes nobody but new players.</p><p>With <code>attack.early-stop = true</code> (default), the once-per-second evaluation tick also feeds the measured join rate into a rolling <code>attack.early-stop-window-seconds</code> window (default 5). When the windowed join count stays below <code>attack.early-stop-joins-per-window</code> (default 8) for <code>attack.early-stop-sustain-seconds</code> (default 3) consecutive seconds, attack mode disengages through the <strong>same transition</strong> as the normal path — logged, and announced through <code>NitroAttackModeEvent</code> like any other disengage.</p><ul><li>The two conditions coexist; <strong>whichever fires first wins.</strong> Early stop only ever shortens an attack, never extends it.</li><li>The window resets on every transition, so a re-engaged attack always starts with fresh samples.</li><li>While a force-engage pin holds (the <a href="/pingless-studios-docs/nitrocord/configuration/reference#amazon">amazon real-client gate</a> pinning attack mode on its own evidence), early-stop evaluation is skipped — the two mechanisms never fight over the engaged state. The remaining lockdown time shown by <code>kick-lockdown</code> counts the pin first, then the normal deactivation delay, and the actual disengage may happen sooner than the estimate when early stop is enabled.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wave attacks and early stop</p><p>An attacker who fires short, intense waves with pauses in between can ride the early stop: the mode disengages in a pause and re-engages on the next wave. The dormant checks re-arm on each transition, so protection is not lost — but if you see the mode flapping in your logs, raise <code>early-stop-sustain-seconds</code> (or lower <code>early-stop-joins-per-window</code>) rather than disabling the feature.</p></div><hr><h2 id="likeliness-scoring" tabindex="-1">Likeliness scoring <a class="header-anchor" href="#likeliness-scoring" aria-label="Permalink to &quot;Likeliness scoring&quot;">​</a></h2><p>Rate-based attack mode answers &quot;are we under attack?&quot;. Likeliness scoring (BotSentry&#39;s weighted model) answers the per-IP follow-up: &quot;is <em>this</em> address part of it?&quot;. While attack mode is engaged, every join is evaluated against a set of weighted conditions; each condition contributes its weight to the address&#39;s score <strong>at most once per attack</strong>, and the moment the sum reaches <code>scoring.score-threshold</code> the address is firewalled with the reason <code>attack likeliness score</code>.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Key</th><th>Default weight</th><th>Awarded when</th></tr></thead><tbody><tr><td>Unknown location</td><td><code>scoring.score-unknown-location</code></td><td><code>50</code></td><td>GeoIP has no answer for the address <em>and</em> anti-VPN has no verdict (see the caveat below)</td></tr><tr><td>Join velocity</td><td><code>scoring.score-join-velocity</code></td><td><code>25</code></td><td>The address joined ≥ <code>score-join-velocity-threshold</code> (35) times within a fixed 60-second window</td></tr><tr><td>Cloned names</td><td><code>scoring.score-cloned-names</code></td><td><code>50</code></td><td>≥ <code>score-cloned-names-threshold</code> (3) distinct usernames joined from the address</td></tr><tr><td>Denied country</td><td><code>scoring.score-denied-country</code></td><td><code>50</code></td><td>The address geolocates to a <code>[country] blacklist</code>ed country</td></tr><tr><td>Denied VPN</td><td><code>scoring.score-denied-vpn</code></td><td><code>50</code></td><td>The address is on the anti-VPN offline blocklist or holds a cached positive verdict</td></tr></tbody></table><p>The firewall threshold is <code>scoring.score-threshold</code> (default <code>50</code>): with the stock weights any single 50-point condition is decisive, while join velocity needs to combine with a second signal. All lookups are in-memory — the country code comes from the GeoIP cache, the VPN side only consults the offline blocklist and the verdict cache — so scoring never blocks a login on a network call.</p><div class="info custom-block"><p class="custom-block-title">The unknown-location caveat</p><p><code>UNKNOWN_LOCATION</code> deliberately requires both intelligence services to actually run: the GeoIP database loaded and <code>antivpn.enabled</code> set. With either of them unconfigured, <em>every</em> address would look &quot;unknown&quot; — and at the default weight (50, equal to the threshold) that alone would firewall legitimate players during an attack. If you run without GeoIP or anti-VPN, this condition silently never fires.</p></div><p>Per-attack state (score cards, join windows) is held in memory with a ten-minute idle bound and is wiped when attack mode disengages — every attack scores from a clean slate. Scoring is a no-op outside attack mode, so it costs nothing on a normal day.</p><hr><h2 id="the-attack-log" tabindex="-1">The attack log <a class="header-anchor" href="#the-attack-log" aria-label="Permalink to &quot;The attack log&quot;">​</a></h2><p>Every likeliness-scoring firewall decision is journaled to <code>nitrocord/attack-log.jsonl</code> in the proxy run directory — one JSON object per line, appended by a daemon thread that batches writes twice a second. Two record shapes exist:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ip&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;203.0.113.50&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;score&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">75</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;conditions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;JOIN_VELOCITY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;points&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CLONED_NAMES&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;points&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;time&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-07-30T21:15:04.123Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;summary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;attack-end&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;firewalled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">261</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;time&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-07-30T21:18:41.006Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>A <strong>firewall record</strong> carries the address, the final score and every condition that contributed points, in award order — the exact evidence for each ban.</li><li>One <strong>summary record</strong> is written when attack mode disengages, counting the addresses scoring firewalled during that attack. An attack that tripped nothing writes no summary, keeping quiet attacks out of the journal.</li></ul><p>The journal is forensics, not enforcement: the in-memory firewall stays authoritative, and under an extreme flood the bounded write queue drops records rather than slowing a Netty event loop. Records still queued at proxy shutdown are flushed synchronously, so a clean stop loses nothing.</p><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/nitrocord/architecture/overview">Architecture Overview →</a> — the pipeline, lifecycle gates and violation system attack mode builds on.</li><li><a href="/pingless-studios-docs/nitrocord/configuration/reference">Configuration Reference →</a> — every key mentioned on this page.</li><li><a href="/pingless-studios-docs/nitrocord/user-guide/api">Plugin API Events →</a> — <code>NitroAttackModeEvent</code> and friends.</li></ul>`,66))])}const E=o(p,[["render",g]]);export{v as __pageData,E as default};
